PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS supporters (id TEXT PRIMARY KEY, identity_hash TEXT UNIQUE NOT NULL, email TEXT, name TEXT NOT NULL, blocked INTEGER NOT NULL DEFAULT 0, muted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, title TEXT NOT NULL, started INTEGER NOT NULL, ended INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session ON sessions((1)) WHERE ended IS NULL;
CREATE TABLE IF NOT EXISTS tips (
 id TEXT PRIMARY KEY, token TEXT UNIQUE NOT NULL, supporter_id TEXT NOT NULL REFERENCES supporters(id),
 name TEXT NOT NULL, display_paise INTEGER NOT NULL CHECK(display_paise>0), requested_paise INTEGER NOT NULL,
 actual_paise INTEGER, message TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL,
 verified INTEGER, session_id TEXT REFERENCES sessions(id), reference TEXT UNIQUE,
 status TEXT NOT NULL CHECK(status IN ('PENDING','VERIFIED','EXPIRED','REFUNDED','MANUAL','REJECTED')),
 tts INTEGER NOT NULL, voice TEXT NOT NULL, sound TEXT NOT NULL, alert_shown INTEGER DEFAULT 0,
 tts_played INTEGER DEFAULT 0, verification_source TEXT, note TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS tips_match ON tips(requested_paise,status,expires);
CREATE INDEX IF NOT EXISTS tips_time ON tips(verified,status);
CREATE TABLE IF NOT EXISTS receipts (reference TEXT PRIMARY KEY, amount INTEGER NOT NULL, received INTEGER NOT NULL, ingested INTEGER NOT NULL, outcome TEXT NOT NULL, tip_id TEXT);
CREATE TABLE IF NOT EXISTS amount_leases (amount INTEGER PRIMARY KEY, until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS goals (id TEXT PRIMARY KEY, title TEXT NOT NULL, target INTEGER NOT NULL CHECK(target>0), starting INTEGER NOT NULL DEFAULT 0, period TEXT NOT NULL, reset TEXT NOT NULL, starts INTEGER, ends INTEGER, enabled INTEGER NOT NULL DEFAULT 1, design TEXT NOT NULL, style TEXT NOT NULL, session_id TEXT);
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, tip_id TEXT REFERENCES tips(id), payload TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deliveries (alert_id INTEGER NOT NULL REFERENCES alerts(id), channel TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', owner TEXT, lease INTEGER, PRIMARY KEY(alert_id,channel));
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES (1);
